//! The files nobody writes by hand, one rule for `bd`, every review of the app and the update, with no git of its own
//! (`git_ops::generated` reads what it needs: the attributes, the starts of the blobs):
//! - `names`: lock files, minified files, source maps and snapshots, by the name alone
//! - `attributes`: the git attributes that mark a file generated, `linguist-generated` or `-diff`
//! - `header`: the files whose leading comment says that a tool wrote them (`Generated by …`, `@generated`)
//! - `generated_by`: why a file is generated, as a review and an update show it, from its name, its attributes and its
//!   texts
//!
//! No policy of a view: what a caller leaves out, folds, refuses to merge or counts is its own.

pub mod attributes;
pub mod generated_by;
pub mod header;
pub mod names;

